import java.util.Scanner;

public class Main {
    static final int MOD = 1000000007;
    static final int DIMENSION = 32;
    static final int MAX_D = 64;
    static final int MAX_K = 32;

    static class Matrix {
        int[][] mat = new int[DIMENSION][DIMENSION];

        Matrix() {
            for (int i = 0; i < DIMENSION; i++) {
                for (int j = 0; j < DIMENSION; j++) {
                    mat[i][j] = 0;
                }
            }
        }

        int[] getRow(int i) {
            return mat[i];
        }

        static Matrix multiply(Matrix A, Matrix B) {
            Matrix R = new Matrix();
            for (int i = 0; i < DIMENSION; i++) {
                for (int j = 0; j < DIMENSION; j++) {
                    for (int k = 0; k < DIMENSION; k++) {
                        R.mat[i][j] = sumMod(R.mat[i][j], productMod(A.mat[i][k], B.mat[k][j]));
                    }
                }
            }
            return R;
        }
    }

    static int sumMod(int a, int b) {
        int s = a + b;
        if (s >= MOD) s -= MOD;
        return s;
    }

    static int productMod(int a, int b) {
        return (int)((long) a * b % MOD);
    }

    static Matrix buildMatrix(int n, int offset, Matrix[] f, int k, int[] fValues) {
        Matrix M = new Matrix();
        for (int i = 0; i <= k; i++) {
            for (int j = 0; j <= k; j++) {
                int ni = (i == k) ? i : (i + offset) % k;
                int nj = (j == k) ? j : (j + offset) % k;
                M.mat[ni][nj] = f[n].mat[i][j];
            }
        }
        return M;
    }

    static int digitSum(long n, int k) {
        int sum = 0;
        while (n > 0) {
            sum += n % k;
            n /= k;
        }
        return sum % k;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int base = sc.nextInt();
        int k = base;

        int digitsCount = 0;
        long temp = n;
        while (temp > 0) {
            temp /= k;
            digitsCount++;
        }

        Matrix[] f = new Matrix[MAX_D];
        for (int i = 0; i < MAX_D; i++) {
            f[i] = new Matrix();
        }

        // Initialize identity matrix
        Matrix identity = new Matrix();
        for (int i = 0; i <= k; i++) {
            identity.mat[i][i] = 1;
        }

        // Initialize f[0]
        f[0] = identity;
        for (int i = 0; i <= k; i++) {
            f[0].mat[i][0] = 1;
        }

        // Precompute f[i]
        for (int i = 1; i < digitsCount; i++) {
            f[i] = identity;
            for (int j = 0; j < k; j++) {
                f[i] = Matrix.multiply(f[i], buildMatrix(i - 1, j, f, k, null));
            }
        }

        long current = 0;
        long power = 1;

        // Decrease digitsCount by 1
        digitsCount--;
        for (int i = 0; i < digitsCount; i++) {
            power *= k;
        }

        Matrix result = new Matrix();
        // Initialize result as identity
        for (int i = 0; i <= k; i++) {
            result.mat[i][i] = 1;
        }

        while (current < n) {
            // assert(digitsCount >= 0); // Not needed in Java
            while (current + power <= n) {
                int[] fValues = new int[k + 1];
                for (int i = 0; i <= k; i++) {
                    fValues[i] = digitSum(current, k);
                }
                result = Matrix.multiply(result, buildMatrix(digitsCount, fValues[digitsCount], f, k, fValues));
                current += power;
            }
            power /= k;
            digitsCount--;
        }

        int total = 0;
        for (int i = 0; i <= k; i++) {
            total = sumMod(total, result.mat[k][i]);
        }
        System.out.println(total);
        sc.close();
    }
}
